def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of 1s connected horizontally or vertically.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            i, j = stack.pop()
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                bfs(i, j)
    return islands

