def solve(grid):
    """Count islands in a binary grid where rows may have variable lengths.
    Cells are adjacent up, down, left, right.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[i]) for i in range(rows) ]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            i, j = stack.pop()
            # four directions
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                bfs(i, j)
    return islands

