def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports '+', '-', '*', '/' with division truncating toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Use absolute division to avoid float precision issues
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

