import itertools, random

def solve(nums):
    if not nums:
        return []
    a = nums[:]
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        return list(sorted(a))
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

def next_perm_ref(arr):
    perms = sorted(set(itertools.permutations(arr)))
    idx = perms.index(tuple(arr))
    if idx + 1 < len(perms):
        return list(perms[idx+1])
    else:
        return list(sorted(arr))

for _ in range(1000):
    length = random.randint(0,5)
    arr = [random.randint(-2,2) for _ in range(length)]
    if solve(arr) != next_perm_ref(arr):
        print('mismatch', arr, solve(arr), next_perm_ref(arr))
        break
else:
    print('all good')

